def _validate_row(row, index):
    if not isinstance(row, dict):
        raise ValueError("contact at index {} must be an object".format(index))
    if set(row.keys()) != {"email", "name"}:
        raise ValueError(
            "contact at index {} must have exactly 'email' and 'name' fields".format(index)
        )
    email = row["email"]
    name = row["name"]
    if not isinstance(email, str):
        raise ValueError("contact at index {} has a non-string 'email'".format(index))
    if not isinstance(name, str):
        raise ValueError("contact at index {} has a non-string 'name'".format(index))
    email = email.strip()
    name = name.strip()
    local, at, domain = email.partition("@")
    if at != "@" or local == "" or domain == "" or "@" in domain:
        raise ValueError(
            "contact at index {} has an invalid 'email': expected exactly one '@' with nonempty local part and domain, and no whitespace".format(index)
        )
    if email != email.strip() or any(ch.isspace() for ch in email):
        raise ValueError(
            "contact at index {} has an invalid 'email': no whitespace is allowed".format(index)
        )
    if name == "":
        raise ValueError("contact at index {} has a nonempty 'name' requirement".format(index))
    return {"email": email.lower(), "name": name, "index": index}


def _validate_batch(rows):
    if not isinstance(rows, (list, tuple)):
        raise ValueError("contacts must be a list of objects")
    validated = []
    seen = set()
    for index, row in enumerate(rows):
        contact = _validate_row(row, index)
        email = contact["email"]
        if email in seen:
            raise ValueError("contact at index {} duplicates email {}".format(index, email))
        seen.add(email)
        validated.append(contact)
    return validated


def _count_existing(connection, emails):
    if not emails:
        return set()
    unique = list(dict.fromkeys(emails))
    placeholders = ",".join("?" for _ in unique)
    rows = connection.execute(
        "SELECT email FROM contacts WHERE email IN ({})".format(placeholders),
        unique,
    ).fetchall()
    return {row[0] for row in rows}


