    contacts = _validate_batch(rows)
    if not contacts:
        return {"inserted": 0, "updated": 0}
    connection.execute("SAVEPOINT {}".format(_SAVEPOINT))
    try:
        existing = select_existing_emails(connection, [c["email"] for c in contacts])
        inserted = sum(1 for c in contacts if c["email"] not in existing)
        updated = len(contacts) - inserted
        for contact in contacts:
            put_contact(connection, contact["email"], contact["name"])
    except BaseException:
        if connection.in_transaction:
            connection.execute("ROLLBACK TO SAVEPOINT {}".format(_SAVEPOINT))
            connection.execute("RELEASE SAVEPOINT {}".format(_SAVEPOINT))
        raise
    connection.execute("RELEASE SAVEPOINT {}".format(_SAVEPOINT))
    return {"inserted": inserted, "updated": updated}


def _validate_batch(rows):
    if not isinstance(rows, (list, tuple)):
        raise ValueError("contacts must be a list of contact objects")
    contacts = []
    seen = set()
    for index, row in enumerate(rows):
        contact = _validate_row(row, index)
        email = contact["email"]
        if email in seen:
            raise ValueError("contact at index {} duplicates email {}".format(index, email))
        seen.add(email)
        contacts.append(contact)
    return contacts


def _validate_row(row, index):
    if not isinstance(row, dict):
        raise ValueError("contact at index {} must be an object".format(index))
    if frozenset(row.keys()) != _REQUIRED_FIELDS:
        raise ValueError(
            "contact at index {} must have exactly the 'email' and 'name' fields".format(index)
        )
    email = row["email"]
    name = row["name"]
    if not isinstance(email, str):
        raise ValueError("contact at index {} has a non-string 'email'".format(index))
    if not isinstance(name, str):
        raise ValueError("contact at index {} has a non-string 'name'".format(index))
    email = email.strip()
    name = name.strip()
    _validate_email(email, index)
    if not name:
        raise ValueError("contact at index {} must have a nonempty 'name'".format(index))
    return {"email": email.lower(), "name": name}


def _validate_email(email, index):
    if not email:
        raise ValueError("contact at index {} must have a nonempty 'email'".format(index))
    if any(char.isspace() for char in email):
        raise ValueError("contact at index {} must have an 'email' without whitespace".format(index))
    local, at, domain = email.partition("@")
    if at != "@" or not local or not domain or "@" in domain:
        raise ValueError(
            "contact at index {} must have an 'email' with exactly one '@' "
            "and nonempty local part and domain".format(index)
        )
