def _extract_contacts(payload):
    if not isinstance(payload, dict):
        raise ValueError("payload must be an object with a 'contacts' field")
    if frozenset(payload.keys()) != frozenset(("contacts",)):
        raise ValueError("payload must have exactly the 'contacts' field")
    rows = payload["contacts"]
    if not isinstance(rows, list):
        raise ValueError("'contacts' must be a list of contact objects")
    return rows
def initialize(connection):
    connection.execute("CREATE TABLE contacts (email TEXT PRIMARY KEY, name TEXT NOT NULL)")
    connection.commit()

def list_contacts(connection):
    return connection.execute("SELECT email, name FROM contacts ORDER BY email").fetchall()

def put_contact(connection, email, name):
    connection.execute("INSERT INTO contacts VALUES (?, ?) ON CONFLICT(email) DO UPDATE SET name=excluded.name", (email, name))

def select_existing_emails(connection, emails):
    found = set()
    unique = list(emails)
    for start in range(0, len(unique), _EXISTING_EMAILS_CHUNK):
        chunk = unique[start:start + _EXISTING_EMAILS_CHUNK]
        placeholders = ",".join("?" for _ in chunk)
        rows = connection.execute(
            "SELECT email FROM contacts WHERE email IN ({})".format(placeholders),
            chunk,
        ).fetchall()
        found.update(row[0] for row in rows)
    return found

